def f(t, C0, k=5.5e-6, n=2.37, m=2.0, C_sat=0.218):
    C = float(C0)
    if t <= 0:
        return C
    N = 2000
    dt = t / N
    for _ in range(N):
        denom = C_sat**m + C**m
        C = C - k * (C**n) / denom * dt
        if C < 0:
            C = 0.0
    return C

